function bindAdminDelete(dialog,user){dialog.querySelector('[data-admin-delete]')?.addEventListener('click',()=>{dialog.close();openAdminDelete(user)})}
function openAdminDelete(user){if(!user||user.role==='admin')return;const dialog=featureDialog('স্থায়ীভাবে অ্যাকাউন্ট ডিলিট','<div class="admin-delete-intro"><span>'+adminButtonIcon('trash')+'</span><h2>এই অ্যাকাউন্ট স্থায়ীভাবে মুছবেন?</h2><p>হিসাব, ছবি, ব্যাকআপ, রিমাইন্ডার ও লগইনসহ সব server data মুছে যাবে। এটি ফিরিয়ে আনা যাবে না।</p></div><div class="admin-delete-person"><strong data-user-text>'+esc(user.name||user.phone)+'</strong><span data-user-text>'+esc(user.phone)+'</span></div><form id="admin-delete-form"><label>নিশ্চিত করতে user-এর মোবাইল নম্বর লিখুন<input type="tel" name="confirmPhone" autocomplete="off" inputmode="tel" required></label><label>অ্যাডমিনের বর্তমান পাসওয়ার্ড<input type="password" name="password" autocomplete="current-password" required></label><p class="danger" id="admin-delete-error" role="alert"></p><div class="admin-delete-actions"><button type="button" id="admin-delete-cancel">বাতিল</button><button type="submit" class="admin-delete-confirm">স্থায়ীভাবে ডিলিট করুন</button></div></form>');dialog.classList.add('admin-delete-dialog');dialog.querySelector('#admin-delete-cancel').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),error=dialog.querySelector('#admin-delete-error');if(values.confirmPhone!==user.phone){error.textContent=featureText('নিশ্চিত করতে user-এর সঠিক মোবাইল নম্বর লিখুন।');return}const controls=Array.from(event.target.querySelectorAll('button,input'));controls.forEach(control=>control.disabled=true);error.textContent='';try{await accountAPI('admin/users/delete','POST',{...values,id:user.id});event.target.reset();dialog.close();adminOffset=0;renderAdmin();alert('অ্যাকাউন্ট স্থায়ীভাবে ডিলিট হয়েছে। এই user চাইলে নতুন করে registration করতে পারবেন।')}catch(e){error.textContent=e.message;controls.forEach(control=>control.disabled=false)}}}
